    button:active { transform: translateY(1px); }

    .success {
      margin-top: 14px;
      padding: 10px 12px;
      font-size: 14px;
      color: #065f46;
      background: #d1fae5;
      border-radius: 8px;
    }

    [hidden] { display: none !important; }
  </style>
</head>
<body>

  <form class="form-card" id="myForm" novalidate>
    <h1>填写你的信息</h1>

    <!-- 姓名 -->
    <div class="form-group">
      <label for="name">姓名 <span class="required">*</span></label>
      <input type="text" id="name" name="name" placeholder="请输入姓名" autocomplete="name">
      <p class="error" id="nameError"></p>
    </div>

    <!-- 邮箱 -->
    <div class="form-group">
      <label for="email">邮箱 <span class="required">*</span></label>
      <input type="email" id="email" name="email" placeholder="name@example.com" autocomplete="email">
      <p class="error" id="emailError"></p>
    </div>

    <!-- 单选 -->
    <div class="form-group">
      <span class="label" style="display:block;margin-bottom:6px;font-size:14px;color:#374151;">
        通知方式 <span class="required">*</span>
      </span>
      <label class="inline">
        <input type="radio" name="contact" value="email"> 邮件
      </label>
      <label class="inline">
        <input type="radio" name="contact" value="sms"> 短信
      </label>
      <label class="inline">
        <input type="radio" name="contact" value="none"> 不接收
      </label>
      <p class="error" id="contactError"></p>
    </div>

    <!-- 复选 -->
    <div class="form-group">
      <label class="inline">
        <input type="checkbox" id="agree" name="agree">
        我已阅读并同意《用户协议》 <span class="required">*</span>
      </label>
      <p class="error" id="agreeError"></p>
    </div>

    <button type="submit">提交</button>

    <div class="success" id="successMsg" hidden>提交成功，感谢你的填写！</div>
  </form>

  <script>
    (function () {
      const form     = document.getElementById('myForm');
      const nameInput = document.getElementById('name');
      const emailInput = document.getElementById('email');
      const agreeBox  = document.getElementById('agree');
      const radios    = Array.from(document.querySelectorAll('input[name="contact"]'));
      const successMsg = document.getElementById('successMsg');

      const errorEls = {
        name:    document.getElementById('nameError'),
        email:   document.getElementById('emailError'),
        contact: document.getElementById('contactError'),
        agree:   document.getElementById('agreeError')
      };

      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      /* ---------- 校验函数：通过返回 true，失败返回 false ---------- */

      function validateName() {
        const value = nameInput.value.trim();
        if (!value) {
          errorEls.name.textContent = '请输入姓名';
          nameInput.classList.add('invalid');
          return false;
        }
        if (value.length < 2) {
          errorEls.name.textContent = '姓名至少需要 2 个字符';
          nameInput.classList.add('invalid');
          return false;
        }
        errorEls.name.textContent = '';
        nameInput.classList.remove('invalid');
        return true;
      }

      function validateEmail() {
        const value = emailInput.value.trim();
        if (!value) {
          errorEls.email.textContent = '请输入邮箱';
          emailInput.classList.add('invalid');
          return false;
        }
        if (!EMAIL_RE.test(value)) {
          errorEls.email.textContent = '邮箱格式不正确，例如 name@example.com';
          emailInput.classList.add('invalid');
          return false;
        }
        errorEls.email.textContent = '';
        emailInput.classList.remove('invalid');
        return true;
      }

      function validateContact() {
        const checked = radios.some(r => r.checked);
        errorEls.contact.textContent = checked ? '' : '请选择一种通知方式';
        return checked;
      }

      function validateAgree() {
        errorEls.agree.textContent = agreeBox.checked ? '' : '请先阅读并同意用户协议';
        return agreeBox.checked;
      }

      function clearAllErrors() {
        Object.values(errorEls).forEach(el => el.textContent = '');
        nameInput.classList.remove('invalid');
        emailInput.classList.remove('invalid');
        successMsg.hidden = true;
      }

      /* ---------- 实时校验：失焦或修改时立即反馈 ---------- */

      nameInput.addEventListener('blur', validateName);
      emailInput.addEventListener('blur', validateEmail);

      nameInput.addEventListener('input', () => {
        if (errorEls.name.textContent) validateName();
      });

      emailInput.addEventListener('input', () => {
        if (errorEls.email.textContent) validateEmail();
      });

      radios.forEach(radio => {
        radio.addEventListener('change', () => {
          if (errorEls.contact.textContent) validateContact();
        });
      });

      agreeBox.addEventListener('change', () => {
        if (errorEls.agree.textContent) validateAgree();
      });

      /* ---------- 提交 ---------- */

      form.addEventListener('submit', function (event) {
        event.preventDefault();   // 阻止默认提交，先做校验
        clearAllErrors();

        // 依次校验，记录第一个失败的控件用于聚焦
        const checks = [
          { ok: validateName(),    el: nameInput },
          { ok: validateEmail(),   el: emailInput },
          { ok: validateContact(), el: radios[0] },
          { ok: validateAgree(),   el: agreeBox }
        ];

        const firstFailed = checks.find(c => !c.ok);

        if (firstFailed) {
          firstFailed.el.focus();
          return;   // 校验不通过，不提交
        }

        // === 校验全部通过：这里可以换成真实的提交逻辑 ===
        successMsg.hidden = false;
        form.reset();
      });
    })();
  </script>

</body>
</html>
```
### 表单的交互与校验方式

**必填校验**：姓名要求非空且至少 2 个字符；邮箱要求非空且格式正确；单选“通知方式”必须选一项；复选“用户协议”必须勾选。  
**实时反馈**：输入框失焦或修改内容时会立即显示或清除错误提示；单选和复选变化后也会即时更新。  
**提交行为**：点击“提交”先阻止默认发送，依次校验所有字段，遇到第一个错误会聚焦到对应控件并停止提交；全部通过后显示成功提示并重置表单。
---

**优化建议：** 当前提交后只显示成功提示并重置表单，如需真实发送数据，可在提交成功分支中调用接口或写入后端。

这是一个可直接运行的 HTML 文档，实现了一个每秒自动更新的倒计时工具，支持传入结束时间、实时回调剩余时间，并在结束时触发提示。
```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>JavaScript 倒计时</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
